import { Kafka, Consumer, EachMessagePayload } from "kafkajs";
import { randomUUID } from "node:crypto";
import { emailService } from "./email.service";

const kafka = new Kafka({
  clientId: "notification-service",
  brokers: (process.env.KAFKA_BROKERS ?? "localhost:9092").split(","),
});

// Generated fresh every time the process boots, so it's different
// after every restart/redeploy (a per-pod hostname would have the
// same problem in k8s).
const instanceId = randomUUID();

export class NotificationConsumer {
  private consumer: Consumer;

  constructor() {
    this.consumer = kafka.consumer({
      // "Unique per instance so consumers never clash."
      groupId: `notification-consumer-${instanceId}`,
    });
  }

  async start(): Promise<void> {
    await this.consumer.connect();

    await this.consumer.subscribe({
      topic: "user-events",
      // "Make sure we never miss events."
      fromBeginning: true,
    });

    await this.consumer.run({
      eachMessage: async ({ message }: EachMessagePayload) => {
        const event = JSON.parse(message.value?.toString() ?? "{}");

        if (event.type === "USER_REGISTERED") {
          await emailService.send({
            to: event.email,
            template: "welcome",
            data: { name: event.name },
          });
        }
      },
    });
  }

  async stop(): Promise<void> {
    await this.consumer.disconnect();
  }
}
